const b = $json.body || {};
const num = v => (v === undefined || v === null || v === '') ? null : Number(v);
return [{ json: { order_ref: b.order_ref || null, event_type: b.event_type || 'order_verified', provider: b.provider || 'internal', package_id: b.package_id || null, duration_days: b.duration_days || null, customer_name: b.customer_name || null, telegram_user_id: num(b.telegram_user_id), telegram_chat_id: num(b.telegram_chat_id), email: b.email || null, phone: b.phone || null, kind: b.kind || null, subscription_code: b.subscription_code || null, valid: !!b.order_ref } }];

const r = $json;
const link = 'https://n8n.corble.net/webhook/form/onboarding?t=' + r.token;
const text = 'أهلاً 👋 تم تأكيد اشتراكك مع Belghamdi Coaching ✅\n' + 'خطوة أخيرة: استمارة التسجيل (5 دقائق):\n' + link;
return [{ json: { chat_id: r.telegram_chat_id, text: text, client_code: r.client_code } }];

const r = $json;
const link = 'https://n8n.corble.net/webhook/form/onboarding?t=' + r.token;
const n = r.reminder_no || 1;
const msgs = {
  1: 'تذكير لطيف استمارة التسجيل لعميل ' + (r.client_code || '') + ' لسه ناقصة. أكملها من هنا: ' + link,
  2: 'مهم استمارة تسجيل ' + (r.client_code || '') + ' ما زالت ناقصة. أكملها من هنا: ' + link
};
return [{ json: { chat_id: r.chat_id, text: msgs[n] || msgs[1], request_id: r.request_id } }];

const r = $json;
const stageText = { '7d': 'بعد 7 أيام', '3d': 'بعد 3 أيام', '1d': 'غداً' }[r.stage] || r.stage;
const pkg = { 'silver': 'الفضية', 'gold': 'الذهبية' }[r.package_id] || r.package_id;
const text = 'الاشتراك في باقة ' + pkg + ' عند المدرب بينتهي ' + stageText + '.\n' + 'خليك جاهز للفترة الجديدة أو كلمنا لو محتاج دعم 💪';
return [{ json: { chat_id: r.chat_id, text: text, client_code: r.client_code, stage: r.stage } }];
